let D=window.DATA;let sourceMode='preview';let year='all',page='geral';const $=s=>document.querySelector(s),fmt=n=>new Intl.NumberFormat('pt-BR',{maximumFractionDigits:1}).format(n),pct=n=>fmt(n*100)+'%',sum=(a,k)=>a.reduce((t,r)=>t+(+r[k]||0),0),avg=(a,k)=>a.length?sum(a,k)/a.length:0;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const titles={python:['Gráficos Python','Explore oito análises com Pandas, NumPy, Matplotlib, Seaborn e WordCloud.'],geral:['Visão geral','Cada round conta. Explore a trajetória da FURIA no servidor.'],mapas:['Mapas','Conheça o território. Compare resultados e tamanho das amostras.'],jogadores:['Jogadores','Os nomes por trás dos números. Performance individual no período.'],adversarios:['Adversários','Confrontos, histórico e contexto para cada rival.'],partidas:['Partidas','Explore os resultados e encontre cada confronto.'],analises:['Análises & dados','Dos dados brutos às perguntas que fazem a diferença.']};
function rows(k){return D[k].filter(r=>year==='all'||String(r.ano)===year)}
function groups(a,k){return Object.entries(a.reduce((o,r)=>((o[r[k]]??=[]).push(r),o),{}))}
function card(label,value,sub,icon='↗'){return `<div class="kpi"><span class="label">${label}</span><span class="icon">${icon}</span><strong>${value}</strong><small>${sub}</small></div>`}
function panel(title,sub,body,tag=''){return `<section class="panel"><div class="paneltop"><div><h3>${title}</h3><div class="sub">${sub}</div></div>${tag?`<span class="tag">${tag}</span>`:''}</div>${body}</section>`}
function bars(items){return `<div class="bars">${items.map(x=>`<div class="barrow"><span>${esc(x[0])}${x[2]?`<small>${esc(x[2])}</small>`:''}</span><div class="track"><div class="fill" style="width:${Math.max(0,Math.min(100,x[1]*100))}%"></div></div><span class="val">${pct(x[1])}</span></div>`).join('')}</div>`}
function line(items){if(!items.length)return '';let w=600,h=190,left=33,right=15,top=12,bottom=30;let pw=w-left-right,ph=h-top-bottom;let points=items.map((r,i)=>[left+i*pw/Math.max(1,items.length-1),top+(1-r[1])*ph]);let poly=points.map(p=>p.join(',')).join(' ');return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Evolução mensal da taxa de vitória, eixo vertical de 0 a 100 por cento"><defs><linearGradient id="shade" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#f3f3ef" stop-opacity=".18"/><stop offset="1" stop-color="#f3f3ef" stop-opacity="0"/></linearGradient></defs>${[0,.25,.5,.75,1].map(v=>`<line class="gridline" x1="${left}" x2="${w-right}" y1="${top+(1-v)*ph}" y2="${top+(1-v)*ph}"/><text x="0" y="${top+(1-v)*ph+3}">${v*100}</text>`).join('')}<polygon points="${left},${h-bottom} ${poly} ${points.at(-1)[0]},${h-bottom}" fill="url(#shade)"/><polyline points="${poly}" fill="none" stroke="#f3f3ef" stroke-width="2"/>${points.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="3" fill="#f3f3ef"><title>${items[i][0]}: ${pct(items[i][1])} (${items[i][2]} mapas)</title></circle>${i%Math.max(1,Math.ceil(items.length/6))===0?`<text x="${p[0]}" y="${h-5}" text-anchor="middle">${items[i][0].slice(5)}/${items[i][0].slice(2,4)}</text>`:''}`).join('')}</svg>`}
function annual(m){return bars(groups(m,'ano').map(([a,r])=>[a,avg(r,'vitoria'),r.length+' mapas']))}
function monthly(m){return line(groups(m.map(r=>({...r,mes:r.data.slice(0,7)})),'mes').sort((a,b)=>a[0].localeCompare(b[0])).map(([a,r])=>[a,avg(r,'vitoria'),r.length]))}
function table(headers,body){return `<div class="tablewrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${body.join('')}</tbody></table></div>`}
function matchtable(p,limit=8){return table(['DATA','CONFRONTO','EVENTO','PLACAR','RESULTADO'],[...p].sort((a,b)=>b.data.localeCompare(a.data)).slice(0,limit).map(r=>`<tr><td>${r.data.split('-').reverse().join('/')}</td><td><strong>FURIA</strong> <span class="muted">vs</span> ${esc(r.adversario)}</td><td>${esc(r.evento)}</td><td>${r.mapas_furia} : ${r.mapas_adversario}</td><td><span class="${r.vitoria?'win':'loss'}">${r.vitoria?'VITÓRIA':'DERROTA'}</span></td></tr>`))}
function render(){let m=rows('mapas_jogados'),p=rows('partidas'),j=rows('jogadores_mapas');$('#title').innerHTML=titles[page][0]+'<span>.</span>';$('#crumb').textContent=titles[page][0];$('#subtitle').textContent=titles[page][1];$('#hero').style.display=page==='geral'?'flex':'none';document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));let k=`<div class="kpis">${card('Vitórias em mapas',pct(avg(m,'vitoria')),sum(m,'vitoria')+' mapas vencidos')}${card('Séries disputadas',fmt(p.length),'Confrontos no período','⚔')}${card('Mapas jogados',fmt(m.length),'Amostra de mapas','▧')}${card('Vitórias em rounds',pct(sum(m,'rounds_furia')/sum(m,'rounds_total')),fmt(sum(m,'rounds_total'))+' rounds disputados','⌁')}</div>`;let mp=groups(m,'mapa').sort((a,b)=>avg(b[1],'vitoria')-avg(a[1],'vitoria'));let html='';
if(page==='geral'){html=k+`<div class="grid">${panel('Evolução da performance','Taxa de vitória em mapas por mês · passe o mouse nos pontos',monthly(m),'MENSAL')}${panel('Territórios de destaque','Melhores mapas por taxa de vitória · amostras diferentes',bars(mp.slice(0,5).map(([a,r])=>[a,avg(r,'vitoria'),r.length+' mapas'])))}${panel('Comparativo anual','Vitórias em mapas por ano · 2026 é parcial',annual(m),'ANUAL')}${panel('Histórico por adversário','Cinco rivais com mais séries · taxa de vitória em séries',bars(groups(p,'adversario').sort((a,b)=>b[1].length-a[1].length).slice(0,5).map(([a,r])=>[a,avg(r,'vitoria'),r.length+' séries'])))}</div><div class="sectiontitle"><h3>Últimos confrontos</h3><button id="allmatches">Ver todas as partidas ↗</button></div>`+matchtable(p,5);}
if(page==='mapas'){html=k+`<div class="note">A taxa de vitória considera mapas completos. Compare os percentuais junto com a quantidade de mapas jogados; uma amostra pequena oferece menos evidência.</div><div class="mapcards">`+mp.map(([a,r])=>`<section class="mapcard"><span class="eyebrow">MAP POOL / CS2</span><h3>${esc(a)}</h3><strong>${pct(avg(r,'vitoria'))}</strong><p>${r.length} mapas disputados · ${sum(r,'vitoria')} vitórias<br>${pct(sum(r,'rounds_furia')/sum(r,'rounds_total'))} dos rounds vencidos</p><div class="track"><div class="fill" style="width:${avg(r,'vitoria')*100}%"></div></div></section>`).join('')+'</div>';}
if(page==='jogadores'){let g=groups(j,'jogador').map(([name,r])=>({name,n:r.length,k:sum(r,'kills'),d:sum(r,'deaths'),a:sum(r,'assists'),adr:avg(r,'adr'),rating:avg(r,'rating')})).sort((a,b)=>b.k/Math.max(1,b.d)-a.k/Math.max(1,a.d));html=k+panel('Performance individual','K/D = soma das kills / soma das mortes. ADR e rating são médias simples por mapa.',table(['JOGADOR','MAPAS','KILLS','DEATHS','ASSISTS','K/D','ADR','RATING MÉDIO'],g.map(r=>`<tr><td><strong>${esc(r.name)}</strong></td><td>${r.n}</td><td>${fmt(r.k)}</td><td>${fmt(r.d)}</td><td>${fmt(r.a)}</td><td style="color:var(--yellow)">${r.d?(r.k/r.d).toFixed(2):'—'}</td><td>${fmt(r.adr)}</td><td>${r.rating.toFixed(2)}</td></tr>`)))+`<div class="note">Os jogadores têm tempos de participação e amostras diferentes. O rating médio dos mapas não equivale ao rating agregado oficial da HLTV. Versões do rating podem variar entre períodos.</div>`;}
if(page==='adversarios'){let g=groups(p,'adversario').sort((a,b)=>b[1].length-a[1].length);html=k+panel('Histórico de confrontos','Todos os adversários no período selecionado. Use a busca para encontrar um rival.',`<input class="search" id="rival" placeholder="Buscar adversário…" aria-label="Buscar adversário"><div id="rivals">${rivalTable(g)}</div>`);}
if(page==='partidas'){html=k+panel('Arquivo de partidas','Resultados de séries completas, ordenados do mais recente ao mais antigo.',`<input class="search" id="matchsearch" placeholder="Buscar adversário ou evento…" aria-label="Buscar partidas"><div id="matches">${matchtable(p,1000)}</div>`);}
if(page==='analises'){let best=mp[0],years=groups(m,'ano').sort((a,b)=>avg(b[1],'vitoria')-avg(a[1],'vitoria'));html=k+`<div class="grid">${panel('Desempenho ao longo do tempo','01 / ANÁLISE EXPLORATÓRIA',annual(m))+panel('A evolução mês a mês','02 / ANÁLISE EXPLORATÓRIA',monthly(m))+panel('Distribuição por mapa','03 / ANÁLISE EXPLORATÓRIA',bars(mp.map(([a,r])=>[a,avg(r,'vitoria'),r.length+' mapas'])))+panel('Ambiente de jogo','04 / ANÁLISE EXPLORATÓRIA · vitórias em mapas',bars(groups(m,'lan').map(([a,r])=>[a==='1'?'LAN':'Online',avg(r,'vitoria'),r.length+' mapas'])))}</div>`+panel('Vitórias e derrotas em séries','05 / ANÁLISE EXPLORATÓRIA',bars([['Vitórias',avg(p,'vitoria'),sum(p,'vitoria')+' séries'],['Derrotas',1-avg(p,'vitoria'),p.length-sum(p,'vitoria')+' séries']]))+`<div class="note"><strong>Leitura dos resultados no filtro atual</strong><br>Maior taxa por mapa: ${esc(best[0])}, com ${pct(avg(best[1],'vitoria'))} em ${best[1].length} mapas.<br>Maior taxa anual: ${years[0][0]}, com ${pct(avg(years[0][1],'vitoria'))}. Estas comparações são descritivas e não demonstram causalidade.</div>`+panel('Sobre esta base','TRANSPARÊNCIA & METODOLOGIA',`<p class="sub">Origem informada no material enviado: HLTV, equipe masculina FURIA. Coleta: 09/10/2026; último mapa informado: 07/10/2026. Dados de 2026 são parciais.<br><br>A base completa contém 243 séries, 553 mapas e 2.765 observações jogador-mapa da FURIA. Cada observação jogador-mapa representa um jogador em um mapa, não uma partida distinta. Os indicadores desta página são calculados no navegador a partir dos CSVs enviados.<br><br>${sourceMode==='supabase'?'Origem ativa: Supabase. As três tabelas foram carregadas e conferidas.':'Origem ativa: cópia local da base, em modo prévia. O Supabase ainda não está disponível para leitura.'} Para o trabalho, mantenha também os scripts Python de limpeza e análise.</p><a href="https://www.hltv.org/team/8297/furia" target="_blank" rel="noopener">Consultar perfil da equipe na HLTV ↗</a>`);}
if(page==='python')html=window.renderPythonGallery(year);$('#view').innerHTML=html;$('#allmatches')?.addEventListener('click',()=>navigate('partidas'));$('#rival')?.addEventListener('input',e=>{$('#rivals').innerHTML=rivalTable(groups(p,'adversario').filter(([a])=>a.toLowerCase().includes(e.target.value.toLowerCase())).sort((a,b)=>b[1].length-a[1].length))});$('#matchsearch')?.addEventListener('input',e=>{$('#matches').innerHTML=matchtable(p.filter(r=>(r.adversario+' '+r.evento).toLowerCase().includes(e.target.value.toLowerCase())),1000)});}
function rivalTable(g){return table(['ADVERSÁRIO','SÉRIES','VITÓRIAS','DERROTAS','TAXA DE VITÓRIA'],g.map(([a,r])=>`<tr><td><strong>${esc(a)}</strong></td><td>${r.length}</td><td>${sum(r,'vitoria')}</td><td>${r.length-sum(r,'vitoria')}</td><td style="color:var(--yellow)">${pct(avg(r,'vitoria'))}</td></tr>`))}
function navigate(p){if(!titles[p])p='geral';page=p;history.replaceState(null,'','#'+p);render();window.scrollTo({top:0,behavior:'smooth'})}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>navigate(b.dataset.page));$('#explore').onclick=()=>navigate('mapas');$('#years').onclick=e=>{if(!e.target.dataset.year)return;year=e.target.dataset.year;document.querySelectorAll('#years button').forEach(b=>b.classList.toggle('selected',b.dataset.year===year));render()};$('#export').onclick=()=>{const key=page==='jogadores'?'jogadores_mapas':page==='partidas'||page==='adversarios'?'partidas':'mapas_jogados';const r=rows(key),keys=Object.keys(r[0]);const quote=x=>'"'+String(x??'').replace(/"/g,'""')+'"';let csv='\uFEFF'+[keys.map(quote).join(';'),...r.map(a=>keys.map(k=>quote(a[k])).join(';'))].join('\r\n');let u=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));let a=document.createElement('a');a.href=u;a.download=`furia-${page}-${year}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000)};window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));navigate(location.hash.slice(1)||'geral');

async function connectDatabase() {
  const status = $('#data-status');
  const retry = $('#retry-db'); if(retry) retry.disabled = true;
  status.textContent = 'Consultando os dados do Supabase…';
  try {
    const fresh = await window.FuriaDB.load(window.FURIA_CONFIG);
    D = fresh; sourceMode = 'supabase'; render();
    $('#source-label').textContent = 'SUPABASE CONECTADO';
    $('#footer-source').textContent = 'Dados carregados do Supabase';
    status.innerHTML = `<strong>Supabase conectado</strong> · ${D.partidas.length} séries, ${D.mapas_jogados.length} mapas e ${D.jogadores_mapas.length} registros jogador-mapa. <button id="retry-db" class="export">↻ Atualizar dados</button>`;
  } catch (error) {
    // Mantém a prévia visível, sempre identificando sua origem.
    $('#source-label').textContent = sourceMode==='supabase'?'SUPABASE · CÓPIA DA SESSÃO':'MODO PRÉVIA · BASE LOCAL';
    $('#footer-source').textContent = sourceMode==='supabase'?'Última consulta ao Supabase nesta sessão':'Prévia com dados locais · Supabase indisponível';
    status.innerHTML = `<strong>${sourceMode==='supabase'?'Não foi possível atualizar.':'Modo prévia com dados locais.'}</strong> ${sourceMode==='supabase'?'Exibindo a última consulta desta sessão.':'O banco ainda não está disponível para leitura.'} <button id="retry-db" class="export">↻ Tentar conexão</button><details><summary>Detalhes da conexão</summary><p id="db-error"></p></details>`;
    $('#db-error').textContent = error.message;
  }
  $('#retry-db').onclick = connectDatabase;
}
connectDatabase();
